// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (M x M)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j  (M x N)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
//
// Mathematical kernel (BLAS-like SYMM, left / lower):
//   for i in 0..M-1
//     for j in 0..N-1
//       temp2 = 0
//       for k in 0..i-1
//         C[k][j] += alpha * B[i][j] * A[i][k];
//         temp2   +=          B[k][j] * A[i][k];
//       C[i][j] = beta * C[i][j]
//                 + alpha * B[i][j] * A[i][i]
//                 + alpha * temp2;
//
// We keep the logical loop order (i outer, then j, then k ascending)
// so that floating‑point operation order is preserved. The main
// optimizations are:
//   - Remove the inner `if (k < i)` branch by restricting the k‑traversal.
//   - Hoist invariant loads of B[i,j] and A[i,i] out of the k‑loop.
//   - Traverse only A when iterating over k, constructing states for
//     B and C explicitly; this keeps loops expressed using traversers
//     while avoiding unnecessary multi-structure coordination on k.
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k (symmetric, lower stored)
	// B: i x j
	#pragma scop
	// Outer loops: iterate over i and j using C and B (they share {i,j}).
	traverser(C, B).template for_dims<'i'>([=, &A](auto trav_i) {
		// trav_i has 'i' fixed; obtain the current i index once.
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// A[i,i] does not depend on j, so load it once per i.
		const num_t Aii = A[idx<'i', 'k'>(i_idx, i_idx)];

		// Create a traverser over the k-dimension of row i of A:
		//   - fix<'i'>(i_idx)     : select row i in A
		//   - slice<'k'>(0, i_idx): restrict k to [0, i_idx)
		//
		// This exactly matches the original condition `k < i` but
		// removes the inner `if (k < i)` branch and guarantees that
		// k is traversed in ascending order 0..i-1.
		auto a_row_trav =
			traverser(A).order(fix<'i'>(i_idx) ^ slice<'k'>(std::size_t(0), i_idx));

		// Loop over j for this fixed i.
		trav_i.template for_dims<'j'>([=, &A, &B, &C, Aii, a_row_trav](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			// B[i,j] is reused for all k for this (i,j) pair.
			const num_t Bij = B[state_ij];

			num_t temp2 = 0;

			// Inner loop over k: only 0 <= k < i_idx, thanks to slice above.
			// a_row_trav has only the 'k' dimension (i was fixed away).
			a_row_trav.for_each([&](auto state_k) {
				auto k_idx = get_index<'k'>(state_k); // 0 .. i_idx-1

				// Reconstruct full state for A[i,k]:
				//   state_k has only 'k'; we add 'i' using state arithmetic.
				auto s_ik = state_k + idx<'i'>(i_idx);
				const num_t Aik = A[s_ik];

				// State for (k,j) in C and B.
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);

				// Update C[k][j] and accumulate temp2 as in the original formula.
				C[s_kj] += alpha * Bij * Aik;
				temp2   +=          B[s_kj] * Aik;
			});

			// Final update of C[i][j] for this (i,j) pair.
			C[state_ij] = beta * C[state_ij]
			            + alpha * Bij * Aii
			            + alpha * temp2;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
