// computation kernel
//
// We compute: C := beta * C + alpha * A * B,
// where A is symmetric (lower part stored).
//
// The implementation is organized in two phases:
//
// 1) Scale C by beta, using a simple traversal over C.
//
// 2) Add alpha * A * B using a symmetric formulation that improves
//    data locality compared to the original version:
//
//    For each row i:
//      - For each k < i:
//          aik = alpha * A[i,k]
//          For all j:
//            C[k,j] += aik * B[i,j];  // uses A[k,i] = A[i,k]
//            C[i,j] += aik * B[k,j];
//      - Diagonal term for row i:
//          aii = alpha * A[i,i]
//          For all j:
//            C[i,j] += aii * B[i,j];
//
//    All inner-most loops iterate over j, which is the contiguous
//    dimension for B and C in the chosen layout (j is inner), giving
//    good cache utilization and vectorization opportunities.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// Phase 1: C = beta * C
	// ------------------------------------------------------------------
	traverser(C).for_each([&](auto state) {
		C[state] *= beta;
	});

	// ------------------------------------------------------------------
	// Phase 2: C += alpha * A * B, with A symmetric (lower stored)
	// ------------------------------------------------------------------
	auto trav_all = traverser(C, A, B);

	// Outer loop over i
	trav_all.template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// --------------------------------------------------------------
		// Off-diagonal contributions: pairs (i, k) with k < i
		// --------------------------------------------------------------
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			auto state_ik = trav_ik.state();
			auto k_idx = get_index<'k'>(state_ik);

			// Only use the stored (lower) part: k < i
			if (k_idx < i_idx) {
				// A[i,k] is constant across the j-loop; precompute once
				const num_t a_ik       = A[state_ik];
				const num_t alpha_a_ik = alpha * a_ik;

				// Inner-most loop over j (contiguous for B and C)
				trav_ik.for_each([&](auto state_ikj) {
					const auto j_idx = get_index<'j'>(state_ikj);

					// State for (i,j): we can reuse state_ikj; C and B
					// ignore the extra 'k' dimension in the state.
					auto s_ij = state_ikj;

					// State for (k,j): change the row index to k
					auto s_kj = idx<'i', 'j'>(k_idx, j_idx);

					// C[k,j] += alpha * A[i,k] * B[i,j]
					C[s_kj] += alpha_a_ik * B[s_ij];

					// C[i,j] += alpha * A[i,k] * B[k,j]
					C[s_ij] += alpha_a_ik * B[s_kj];
				});
			}
		});

		// --------------------------------------------------------------
		// Diagonal contribution for row i: A[i,i] * B[i,*]
		// --------------------------------------------------------------
		const num_t a_ii       = A[idx<'i', 'k'>(i_idx, i_idx)];
		const num_t alpha_a_ii = alpha * a_ii;

		// Iterate j for this fixed i
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();

			// C[i,j] += alpha * A[i,i] * B[i,j]
			C[state_ij] += alpha_a_ii * B[state_ij];
		});
	});

	#pragma endscop
}

