// computation kernel
//
// Original mathematical kernel (PolyBench SYMM):
//   for i in 0..M-1
//     for j in 0..N-1
//       temp2 = 0
//       for k in 0..i-1
//         C[k][j] += alpha * B[i][j] * A[i][k]
//         temp2   +=          B[k][j] * A[i][k]
//       C[i][j] = beta * C[i][j] + alpha * B[i][j]*A[i][i] + alpha*temp2
//
// A is symmetric (only the lower triangle is stored), but we always access
// it as A[i][k] with k <= i.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j  (row-major: i outer, j inner)
	// A: i x k  (row-major: i outer, k inner; symmetric, lower stored)
	// B: i x j  (row-major)

	#pragma scop
	// Outer loop over i
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// Middle loop over j (inner dimension of C and B -> good locality)
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx    = get_index<'j'>(state_ij);

			// State for (i, j) – reused several times
			auto s_ij = state_ij;

			// Cache B[i][j] and C[i][j] in registers – used in the whole k-loop
			const num_t bij = B[s_ij];
			num_t       cij = C[s_ij];

			num_t temp2 = 0;

			// Inner loop over k, but only for k < i.
			//
			// Instead of traversing the whole 'k' dimension and guarding with
			// "if (k < i)", we build a sliced view that only contains k in
			// [0, i). This:
			//   * avoids the branch inside the innermost loop,
			//   * reduces the number of iterations,
			//   * keeps the iteration fully expressed via a Noarr traverser.
			auto k_slice = slice<'k'>(0, i_idx); // start = 0, length = i_idx

			trav_ij.order(k_slice).for_each([&](auto state_ijk) {
				// state_ijk has 'i', 'j', 'k'
				auto k_idx = get_index<'k'>(state_ijk);

				// A[i][k] – 'j' is ignored by A
				const num_t aik = A[state_ijk];

				// We need C[k][j] and B[k][j], i.e., row index = k, column = j.
				// Build a state with 'i' = k and 'j' = j_idx.
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);

				// Update symmetric contributions:
				//   C[k][j] += alpha * B[i][j] * A[i][k]
				//   temp2   +=          B[k][j] * A[i][k]
				C[s_kj] += alpha * bij * aik;
				temp2   += B[s_kj] * aik;
			});

			// Diagonal element A[i][i]
			const num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];

			// Final update of C[i][j]:
			//   C[i][j] = beta*C[i][j] + alpha*B[i][j]*A[i][i] + alpha*temp2
			C[s_ij] = beta * cij
			        + alpha * bij * a_ii
			        + alpha * temp2;
		});
	});
	#pragma endscop
}

