 *
 * Now the inner-most j-loop walks C, B and temp2 contiguously in memory
 * (row-major layout: j is the innermost dimension). A[i][k] is hoisted
 * out of the j-loop. This greatly improves spatial locality for C and B.
 *
 * All loops are expressed using Noarr traversers and states, as required.
 */
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Length of the column dimension (j), used for the temporary accumulator
	auto n = C | get_length<'j'>();

	// Per-row temporary: temp2[j] accumulates
	//   temp2[j] = sum_{k<i} B[k][j] * A[i][k]
	//
	// We keep it as a 1D Noarr bag so that it can be traversed with Noarr.
	auto temp2 = noarr::bag(noarr::scalar<num_t>() ^ noarr::vector<'j'>(n));

	// C: i x j
	// A: i x k (symmetric, lower part stored)
	// B: i x j
	#pragma scop
	// Outer loop over i (row index)
	noarr::traverser(C, A, B, temp2).template for_dims<'i'>([&](auto trav_i) {
		// Current row index i
		auto state_i = trav_i.state();
		auto i_idx   = noarr::get_index<'i'>(state_i);

		// --------------------------------------------------------------------
		// 1) Initialize temp2[j] = 0 for this row i (all columns j)
		// --------------------------------------------------------------------
		noarr::traverser(temp2).for_each([&](auto s_j) {
			temp2[s_j] = (num_t)0;
		});

		// --------------------------------------------------------------------
		// 2) For all k < i:
		//      - update C[k][j] for all j
		//      - accumulate temp2[j] for all j
		//
		//    C[k][j] += alpha * B[i][j] * A[i][k];
		//    temp2[j] +=        B[k][j] * A[i][k];
		//
		// We iterate k via for_dims<'k'> and j via a nested for_dims<'j'>.
		// The inner-most j-loop walks B and C along the contiguous j-dimension.
		// --------------------------------------------------------------------
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			auto state_ik = trav_ik.state();
			auto k_idx    = noarr::get_index<'k'>(state_ik);

			// We only use the strictly lower triangular part: k < i
			if (k_idx >= i_idx)
				return;

			// A[i][k] is constant for all j in the inner loop, so we load it once
			// and also pre-multiply by alpha.
			num_t a_ik        = A[trav_ik];           // A[i][k]
			num_t alpha_a_ik  = alpha * a_ik;

			// Inner loop over all columns j for the fixed (i, k)
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				auto state_ikj = trav_ikj.state();
				auto j_idx     = noarr::get_index<'j'>(state_ikj);

				// B[i][j] from current (i, j)
				num_t B_ij = B[trav_ikj];

				// Build a state for row k, column j: (k, j)
				auto s_kj = noarr::idx<'i', 'j'>(k_idx, j_idx);

				// C[k][j] += alpha * B[i][j] * A[i][k]
				C[s_kj] += B_ij * alpha_a_ik;

				// temp2[j] += B[k][j] * A[i][k]
				// temp2 only depends on j, so we can index it by the current j-state.
				temp2[trav_ikj] += B[s_kj] * a_ik;
			});
		});

		// --------------------------------------------------------------------
		// 3) Final update of C[i][j] for all j using accumulated temp2[j]:
		//
		//    C[i][j] = beta * C[i][j]
		//              + alpha * B[i][j] * A[i][i]
		//              + alpha * temp2[j];
		// --------------------------------------------------------------------
		num_t a_ii = A[noarr::idx<'i', 'k'>(i_idx, i_idx)]; // diagonal element A[i][i]

		noarr::traverser(temp2).for_each([&](auto s_j) {
			auto j_idx = noarr::get_index<'j'>(s_j);

			// State for (i, j)
			auto s_ij = noarr::idx<'i', 'j'>(i_idx, j_idx);

			num_t C_ij = C[s_ij];
			num_t B_ij = B[s_ij];
			num_t t2   = temp2[s_j];

			C[s_ij] = beta * C_ij
				+ alpha * B_ij * a_ii
				+ alpha * t2;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
